class Solution {
    fun addOneRow(root:TreeNode?,`val`:Int,depth:Int):TreeNode?{
        if(depth==1){
            val added=TreeNode(`val`);
            added.left=root;
            return added
        };
        fun insert(node:TreeNode?,current:Int){
            if(node==null)return;
            if(current==depth-1){
                val oldLeft=node.left;
                val oldRight=node.right;
                node.left=TreeNode(`val`);
                node.right=TreeNode(`val`);
                node.left!!.left=oldLeft;
                node.right!!.right=oldRight;
                return
            };
            insert(node.left,current+1);
            insert(node.right,current+1)
        };
        insert(root,1);
        return root
    }
}

